   431  void StringPrimitive::appendUTF16String(
   432      llvh::SmallVectorImpl<char16_t> &str) const {
   433    if (isASCII()) {
   434      const char *ptr = castToASCIIPointer();
   435      str.append(ptr, ptr + getStringLength());
   436    } else {
   437      const char16_t *ptr = castToUTF16Pointer();
   438      str.append(ptr, ptr + getStringLength());
   439    }
   440  }
