   442  void StringPrimitive::appendUTF16String(char16_t *ptr) const {
   443    if (isASCII()) {
   444      const char *src = castToASCIIPointer();
   445      std::copy(src, src + getStringLength(), ptr);
   446    } else {
   447      const char16_t *src = castToUTF16Pointer();
   448      std::copy(src, src + getStringLength(), ptr);
   449    }
   450  }
